          <input v-model.number="npcCreatePosition.y" type="number" step="0.1" placeholder="Y" />
          <input v-model.number="npcCreatePosition.z" type="number" step="0.1" placeholder="Z" />
          <button type="button" @click="setNPCPositionToPlayer">📍玩家位置</button>
