          <select v-model="selectedNPCModelId">
            <option value="">随机选择</option>
            <option v-for="model in availableModels" :key="model.id" :value="model.id">
              {{ model.name }} ({{ model.id }})
            </option>
          </select>
        </label>
        <button class="debug-button" type="button" @click="createSingleNPC">➕ 创建单个NPC</button>
        <button class="debug-button" type="button" @click="createRandomNPCs">🎲 随机创建5个NPC</button>
        <div class="button-row">
          <button class="debug-button primary" type="button" @click="setAllNPCsWander">🚶 全部漫游</button>
          <button class="debug-button warning" type="button" @click="setAllNPCsIdle">🧍 全部静止</button>
