        <button class="debug-button danger" type="button" @click="clearAllNPCs">🗑️ 清除所有NPC</button>
        <div v-if="npcList.length" class="npc-list">
          <div v-for="npc in npcList" :key="npc.id" class="npc-item">
            <strong>{{ npc.modelConfig.name }} ({{ npc.id }})</strong>
            <div class="button-row compact">
              <button type="button" @click="setNPCWander(npc.id)">🚶 漫游</button>
              <button type="button" @click="setNPCIdle(npc.id)">🧍 静止</button>
              <button type="button" @click="setNPCPathfindToPlayer(npc.id)">🎯 寻路</button>
              <button type="button" @click="toggleNPCAnimation(npc.id)">🎭</button>
              <button type="button" @click="removeNPC(npc.id)">❌</button>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section class="audio-section">
      <h5>音频</h5>
      <div class="info-item">
        <span>AudioContext:</span><strong>{{ audioCtxState }}</strong>
      </div>
      <label class="slider-label"
        >BGM 主音量: {{ bgmMasterVolume }}%<input
          :value="bgmMasterVolume"
          type="range"
          min="0"
          max="100"
          step="1"
          @input="onAudioBgmMasterChange"
      /></label>
      <label class="slider-label"
        >SFX 主音量: {{ sfxMasterVolume }}%<input
          :value="sfxMasterVolume"
          type="range"
          min="0"
          max="100"
          step="1"
          @input="onAudioSfxMasterChange"
      /></label>
      <div class="button-row">
        <button class="debug-button primary" type="button" @click="setMuted(!muted)">
          {{ muted ? '取消静音' : '静音' }}
        </button>
        <button class="debug-button warning" type="button" @click="stopAllLocalAudioTracks">停止全部本地音频</button>
      </div>
      <div class="local-audio-panel">
        <strong>本地文件试听</strong>
        <label
          >目标:<select v-model="localAudioTarget">
            <option value="bgm">BGM</option>
            <option value="sfx">SFX</option>
          </select></label
        >
        <label
          >类型:<select v-model="localAudioKind">
            <option value="2d">2D</option>
            <option value="3d">3D</option>
          </select></label
        >
        <label
          >Zone:<select v-model="localAudioZoneId">
            <option value="">无</option>
            <option v-for="zone in zones" :key="zone.id" :value="zone.id">{{ zone.id }}</option>
          </select></label
        >
        <input
          ref="localAudioFileInput"
          class="hidden-file-input"
          type="file"
          accept=".mp3,.wav,.aac,.m4a"
          @change="onAudioFileSelect"
        />
        <button class="debug-button" type="button" @click="triggerLocalAudioInput">选择并试听本地音频</button>
      </div>
      <div>
        <strong>当前音轨</strong>
        <div v-if="tracks.length === 0" class="empty-state">无</div>
        <div v-for="track in tracks" :key="track.id" class="track-card">
          <div class="track-header">
            <span>{{ track.id }} ({{ track.target }}/{{ track.kind }})</span
            ><strong>{{ track.playing ? 'playing' : 'paused' }}</strong>
          </div>
          <input
            :value="Math.round(track.volume * 100)"
            type="range"
            min="0"
            max="100"
            step="1"
            @input="onAudioTrackVolumeChange(track, $event)"
          />
          <div class="button-row compact">
            <button type="button" @click="playAudioTrack(track)">播放</button
            ><button type="button" @click="stopAudioTrack(track)">停止</button>
          </div>
        </div>
      </div>
      <div class="audio-zone-section">
        <strong>AudioZone 可视化</strong>
        <label class="debug-checkbox"
          ><input v-model="audioZoneWireframeEnabled" type="checkbox" @change="onAudioZoneWireframeToggle" /><span
            >在场景中显示 AudioZone 线框模型</span
          ></label
        >
        <div class="zone-summary">
          <span>总数 {{ zoneDebugCards.length }}</span
          ><span class="inside">命中 {{ insideZoneCount }}</span
          ><span>外部 {{ zoneDebugCards.length - insideZoneCount }}</span>
        </div>
        <div v-if="playerInsideZones.length" class="inside-zones">当前所在: {{ playerInsideZones.join(', ') }}</div>
        <div v-if="zoneDebugCards.length === 0" class="empty-state">无</div>
        <div v-for="zone in zoneDebugCards" :key="zone.id" class="zone-card" :class="{ inside: zone.inside }">
          <div class="track-header">
            <strong>{{ zone.id }}</strong
            ><span>{{ zone.inside ? 'IN' : 'OUT' }} · {{ zone.shape.toUpperCase() }}</span>
          </div>
          <span>Center: {{ formatVector3(zone.center) }}</span>
          <span>Shape: {{ formatZoneShapeMetric(zone) }}</span>
          <span>BGM: {{ zone.bgmTrackIds.length ? zone.bgmTrackIds.join(', ') : '-' }}</span>
          <span>SFX: {{ zone.sfxTrackIds.length ? zone.sfxTrackIds.join(', ') : '-' }}</span>
        </div>
      </div>
