<script setup lang="ts">
/**
 * @changelog
 *   v1.0.0 - 从 DebugPanel 迁移 NPC 管理、音频试听、音轨管理和 AudioZone 可视化。
 *            REQ: debugpanel-拆分-阶段2 TECH: scene-panel-entity-subpanel
 * /@changelog
 *
 * @author DannyCheung
 */
import * as THREE from 'three';
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue';
import {
  LocalModelConfig,
  getModule,
  createNPC as npcCreateNPC,
  createRandomNPCsInArea as npcCreateRandomNPCsInArea,
  getAllNPCs as npcGetAllNPCs,
  getNPC as npcGetNPC,
  removeNPC as npcRemoveNPC,
  rendererModule,
  setNPCAnimation as npcSetNPCAnimation,
  setNPCPathfindToPlayer as npcSetNPCPathfindToPlayer,
  type AudioDebugTrackSnapshot,
  type NPCInstance,
  type RendererModuleState,
} from '@tencent/viewer-sdk';
import { useAudioParams } from '../composables/useAudioParams';
import { useEngineContextGetter } from '../composables/useEngineContext';

interface Vector3Like {
  x: number;
  y: number;
  z: number;
}
const props = defineProps<{
  debugManager?: { getPhysicsInfo?: () => { characterPosition?: Vector3Like | null } | null };
}>();
const getCtx = useEngineContextGetter();
const {
  audioCtxState,
  bgmMasterVolume,
  sfxMasterVolume,
  muted,
  tracks,
  zones,
  playerInsideZones,
  setBgmMasterVolume,
  setSfxMasterVolume,
  setMuted,
  setTrackVolume,
  play,
  stop,
  loadAndPlayLocal,
  stopLocal,
} = useAudioParams(getCtx);

const npcCreatePosition = reactive({ x: 0, y: 1, z: 5 });
const selectedNPCModelId = ref('');
const npcList = ref<NPCInstance[]>([]);
const npcCount = computed(() => npcList.value.length);
const availableModels = computed(() => LocalModelConfig.models);
const localAudioTarget = ref<'bgm' | 'sfx'>('bgm');
const localAudioKind = ref<'2d' | '3d'>('2d');
const localAudioZoneId = ref('');
const localAudioFileInput = ref<HTMLInputElement | null>(null);
const audioZoneWireframeEnabled = ref(false);
let npcRefreshTimer: ReturnType<typeof setInterval> | null = null;
let audioZoneWireframeGroup: THREE.Group | null = null;
const AUDIO_ZONE_WIREFRAME_GROUP_NAME = 'DebugAudioZoneWireframes';

const zoneDebugCards = computed(() => {
  const bindings = new Map<string, { bgmTrackIds: string[]; sfxTrackIds: string[] }>();
  for (const track of tracks.value) {
    if (!track.zoneId) continue;
    const binding = bindings.get(track.zoneId) ?? { bgmTrackIds: [], sfxTrackIds: [] };
    binding[track.target === 'bgm' ? 'bgmTrackIds' : 'sfxTrackIds'].push(track.id);
    bindings.set(track.zoneId, binding);
  }
  return zones.value
    .map((zone) => ({ ...zone, ...(bindings.get(zone.id) ?? { bgmTrackIds: [], sfxTrackIds: [] }) }))
    .sort((left, right) => Number(right.inside) - Number(left.inside) || left.id.localeCompare(right.id));
});
const insideZoneCount = computed(() => zoneDebugCards.value.filter((zone) => zone.inside).length);

function setNPCPositionToPlayer(): void {
  const position = props.debugManager?.getPhysicsInfo?.()?.characterPosition;
  if (!position) return;
  npcCreatePosition.x = Math.round(position.x * 10) / 10;
  npcCreatePosition.y = Math.round(position.y * 10) / 10;
  npcCreatePosition.z = Math.round(position.z * 10) / 10;
}

async function createSingleNPC(): Promise<void> {
  const ctx = getCtx();
  if (!ctx) return;
  try {
    await npcCreateNPC(ctx, { position: { ...npcCreatePosition }, modelId: selectedNPCModelId.value || undefined });
    updateNPCList();
  } catch (error) {
    console.error('创建NPC失败:', error);
  }
}

async function createRandomNPCs(): Promise<void> {
  const ctx = getCtx();
  if (!ctx) return;
  try {
    await npcCreateRandomNPCsInArea(ctx, { ...npcCreatePosition }, 3, 5);
    updateNPCList();
  } catch (error) {
    console.error('批量创建NPC失败:', error);
  }
}

function clearAllNPCs(): void {
  const ctx = getCtx();
  if (!ctx) return;
  npcGetAllNPCs(ctx).forEach((npc) => npcRemoveNPC(ctx, npc.id));
  updateNPCList();
}
function removeNPC(id: string): void {
  const ctx = getCtx();
  if (!ctx) return;
  npcRemoveNPC(ctx, id);
  updateNPCList();
}
function toggleNPCAnimation(id: string): void {
  const ctx = getCtx();
  if (!ctx || !npcGetNPC(ctx, id)) return;
  npcSetNPCAnimation(ctx, id, ['Idle', 'Walking', 'Running'][Math.floor(Math.random() * 3)]);
}
function setNPCWander(id: string): void {
  const ctx = getCtx();
  const npc = ctx && npcGetNPC(ctx, id);
  npc?.npc?.setMovementPattern('wander');
}
function setNPCIdle(id: string): void {
  const ctx = getCtx();
  const npc = ctx && npcGetNPC(ctx, id);
  npc?.npc?.setMovementPattern('idle');
}
function setNPCPathfindToPlayer(id: string): void {
  const ctx = getCtx();
  if (ctx) npcSetNPCPathfindToPlayer(ctx, id);
}
function setAllNPCsWander(): void {
  const ctx = getCtx();
  if (ctx) npcGetAllNPCs(ctx).forEach((npc) => npc.npc?.setMovementPattern('wander'));
}
function setAllNPCsIdle(): void {
  const ctx = getCtx();
  if (ctx) npcGetAllNPCs(ctx).forEach((npc) => npc.npc?.setMovementPattern('idle'));
}
function updateNPCList(): void {
  const ctx = getCtx();
  if (ctx) npcList.value = npcGetAllNPCs(ctx);
}

function onAudioBgmMasterChange(event: Event): void {
  setBgmMasterVolume(Number((event.target as HTMLInputElement).value));
}
function onAudioSfxMasterChange(event: Event): void {
  setSfxMasterVolume(Number((event.target as HTMLInputElement).value));
}
function onAudioTrackVolumeChange(track: AudioDebugTrackSnapshot, event: Event): void {
  setTrackVolume(track.target, track.id, Number((event.target as HTMLInputElement).value));
}
function triggerLocalAudioInput(): void {
  localAudioFileInput.value?.click();
}
async function onAudioFileSelect(event: Event): Promise<void> {
  const input = event.target as HTMLInputElement;
  const file = input.files?.[0];
  if (!file) return;
  try {
    await loadAndPlayLocal(file, localAudioKind.value, localAudioTarget.value, {
      zoneId: localAudioZoneId.value || undefined,
    });
  } catch (error) {
    console.warn('本地音频试听失败:', error);
  } finally {
    input.value = '';
  }
}
function playAudioTrack(track: AudioDebugTrackSnapshot): void {
  play(track.target, track.id);
}
function stopAudioTrack(track: AudioDebugTrackSnapshot): void {
  track.local ? stopLocal(track.id) : stop(track.target, track.id);
}
function stopAllLocalAudioTracks(): void {
  stopLocal();
}

function getAudioZoneDebugScene(): THREE.Scene | null {
  const ctx = getCtx();
  if (!ctx) return null;
  try {
    return getModule<RendererModuleState>(ctx, rendererModule).scene ?? null;
  } catch {
    return null;
  }
}
function disposeAudioZoneWireframeObjects(removeFromScene = false): void {
  if (!audioZoneWireframeGroup) return;
  const group = audioZoneWireframeGroup;
  group.children.forEach((child) => {
    const mesh = child as THREE.Mesh;
    mesh.geometry?.dispose();
    Array.isArray(mesh.material) ? mesh.material.forEach((material) => material.dispose()) : mesh.material?.dispose();
  });
  group.clear();
  if (removeFromScene) {
    group.parent?.remove(group);
    audioZoneWireframeGroup = null;
  }
}
function syncAudioZoneWireframes(): void {
  if (!audioZoneWireframeEnabled.value) return;
  const scene = getAudioZoneDebugScene();
  if (!scene) return;
  if (audioZoneWireframeGroup?.parent !== scene) {
    disposeAudioZoneWireframeObjects(true);
    audioZoneWireframeGroup = new THREE.Group();
    audioZoneWireframeGroup.name = AUDIO_ZONE_WIREFRAME_GROUP_NAME;
    scene.add(audioZoneWireframeGroup);
  }
  disposeAudioZoneWireframeObjects();
  for (const zone of zoneDebugCards.value) {
    const geometry =
      zone.shape === 'sphere'
        ? new THREE.SphereGeometry(Math.max(zone.radius ?? 0.1, 0.1), 16, 12)
        : new THREE.BoxGeometry(
          Math.max(zone.size?.x ?? 0.1, 0.1),
          Math.max(zone.size?.y ?? 0.1, 0.1),
          Math.max(zone.size?.z ?? 0.1, 0.1),
        );
    const mesh = new THREE.Mesh(
      geometry,
      new THREE.MeshBasicMaterial({
        color: zone.inside ? 0x4caf50 : 0x00bcd4,
        wireframe: true,
        transparent: true,
        opacity: zone.inside ? 0.95 : 0.65,
        depthTest: false,
      }),
    );
    mesh.position.set(zone.center.x, zone.center.y, zone.center.z);
    mesh.renderOrder = 1000;
    audioZoneWireframeGroup.add(mesh);
  }
}
function onAudioZoneWireframeToggle(): void {
  if (audioZoneWireframeEnabled.value) {
    syncAudioZoneWireframes();
    return;
  }
  disposeAudioZoneWireframeObjects(true);
}
function formatVector3(value: Vector3Like): string {
  return `(${value.x.toFixed(2)}, ${value.y.toFixed(2)}, ${value.z.toFixed(2)})`;
}
function formatZoneShapeMetric(zone: { shape: 'sphere' | 'box'; radius?: number; size?: Vector3Like }): string {
  return zone.shape === 'sphere'
    ? `radius=${(zone.radius ?? 0).toFixed(2)}`
    : `size=(${(zone.size?.x ?? 0).toFixed(2)}, ${(zone.size?.y ?? 0).toFixed(2)}, ${(zone.size?.z ?? 0).toFixed(2)})`;
}

onMounted(() => {
  updateNPCList();
  npcRefreshTimer = setInterval(updateNPCList, 1000);
});
onUnmounted(() => {
  if (npcRefreshTimer) clearInterval(npcRefreshTimer);
  disposeAudioZoneWireframeObjects(true);
});
watch(
  zoneDebugCards,
  () => {
    if (audioZoneWireframeEnabled.value) syncAudioZoneWireframes();
  },
  { deep: true },
);
</script>

