import * as THREE from 'three';
import { reactive, ref } from 'vue';
import type { EngineContext, LightCullingState, LightState } from '@tencent/viewer-sdk';
import { lightCullingModule, lightModule, getModule } from '@tencent/viewer-sdk';

export interface LightCullingPanelParams {
  /** 是否启用裁剪 */
  enabled: boolean;
  /** 最大同时启用的可裁剪光源数 */
  maxActiveLights: number;
  /** 距离上限（米，0=不限） */
  maxDistance: number;
  /** 刷新节流（毫秒） */
  updateIntervalMs: number;
  /** 当前候选光源总数 */
  candidateCount: number;
  /** 当前实际启用的光源数（visible=true 的 PointLight/SpotLight） */
  activeCount: number;
}

/**
 * useLightCullingParams — 光源槽位裁剪 DebugPanel 状态 + 命令式 action 封装。
 *
 * 设计遵循 useHdriParams 范式：
 * - `getCtx()` 工厂返回 `EngineContext | undefined`
 * - 所有 action 内置 try/catch 探测 `lightCullingModule` 是否注册
 * - `refreshSnapshot` 按轮询读取快照
 */
export function useLightCullingParams(getCtx: () => EngineContext | undefined) {
  /** 面板参数 */
  const cullingParams = reactive<LightCullingPanelParams>({
    enabled: false,
    maxActiveLights: 8,
    maxDistance: 0,
    updateIntervalMs: 200,
    candidateCount: 0,
    activeCount: 0,
  });

  /** 模块是否已注册 */
  const cullingRegistered = ref(false);

  /**
   * 从 lightCullingModule 读取当前状态快照。
   * 模块未注册时静默跳过，`cullingRegistered` 置 false。
   */
  function refreshSnapshot(): void {
    const ctx = getCtx();
    if (!ctx) return;

    try {
      const state = getModule<LightCullingState>(ctx, lightCullingModule);
      cullingParams.enabled = state.enabled;
      cullingParams.maxActiveLights = state.maxActiveLights;
      cullingParams.maxDistance = state.maxDistanceSq > 0 ? Math.sqrt(state.maxDistanceSq) : 0;
      cullingParams.updateIntervalMs = state.updateIntervalMs;
      cullingRegistered.value = true;

      // 统计：遍历 lightGroup 下所有可裁剪光源，数当前 active 数量
      const { lightGroup } = getModule<LightState>(ctx, lightModule);
      let candidate = 0;
      let active = 0;
      lightGroup.traverse((obj) => {
        const light = obj as THREE.Light & { isPointLight?: boolean; isSpotLight?: boolean };
        if ((light.isPointLight || light.isSpotLight) && light.isLight) {
          candidate++;
          if (light.visible) active++;
        }
      });
      cullingParams.candidateCount = candidate;
      cullingParams.activeCount = active;
    } catch {
      cullingRegistered.value = false;
    }
  }

  /** 运行时开关裁剪 */
  function setEnabled(enabled: boolean): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      lightCullingModule.setEnabled(ctx, enabled);
      cullingParams.enabled = enabled;
    } catch {
      /* 未注册，忽略 */
    }
  }

  /** 运行时调整槽位数 */
  function setMaxActiveLights(n: number): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      lightCullingModule.setMaxActiveLights(ctx, n);
      cullingParams.maxActiveLights = n;
    } catch {
      /* 未注册，忽略 */
    }
  }

  return {
    cullingParams,
    cullingRegistered,
    refreshSnapshot,
    setEnabled,
    setMaxActiveLights,
  };
}
