<template>
  <div v-if="showDebugPanel" class="debug-panel">
    <div class="debug-header">
      <h3>🔧 Debug Panel</h3>
      <button class="close-btn" @click="togglePanel">×</button>
    </div>

    <div class="debug-content">
      <section class="debug-section panel-toggle-section">
        <h4>🗂 面板</h4>
        <div class="panel-toggle-group">
          <button class="panel-toggle-btn" :class="{ active: environmentPanelVisible }" @click="emit('toggleEnvironmentPanel')">🌍 环境面板</button>
          <button class="panel-toggle-btn" :class="{ active: scenePanelVisible }" @click="emit('toggleScenePanel')">🎬 场景面板</button>
        </div>
      </section>

      <section v-if="enableSecondShareVisible" class="debug-section">
        <h4>📤 分享</h4>
        <label class="debug-checkbox"><input v-model="enableSecondShare" type="checkbox" @change="onEnableSecondShareChange" /><span>允许二次分享</span></label>
      </section>

      <section v-if="cullingRegistered" class="debug-section">
        <h4>🔦 光源槽位裁剪</h4>
        <label class="debug-checkbox"><input :checked="cullingParams.enabled" type="checkbox" @change="setCullingEnabled(($event.target as HTMLInputElement).checked)" /><span>启用裁剪</span></label>
        <div class="info-item"><span>候选光源:</span><strong>{{ cullingParams.candidateCount }}</strong></div>
        <div class="info-item"><span>实际启用:</span><strong>{{ cullingParams.activeCount }} / {{ cullingParams.maxActiveLights }}</strong></div>
        <label class="slider-label">槽位数: {{ cullingParams.maxActiveLights }}<input :value="cullingParams.maxActiveLights" type="range" min="1" max="64" step="1" @input="setMaxActiveLights(Number(($event.target as HTMLInputElement).value))" /></label>
      </section>

      <section v-if="scheduleRegistered" class="debug-section">
        <h4>🕐 TOD 定时开关灯</h4>
        <div class="info-item"><span>调度条数:</span><strong>{{ scheduleCount }}</strong></div>
        <div class="info-item"><span>调度灯光:</span><strong>{{ scheduledLightCount }} 盏</strong></div>
        <div class="info-item"><span>当前亮:</span><strong>{{ activeOnCount }} 盏</strong></div>
        <div v-for="schedule in scheduleSummaries" :key="schedule.name" class="schedule-card">
          <strong>{{ schedule.name }}</strong><span>{{ schedule.onHour.toFixed(1) }}h → {{ schedule.offHour.toFixed(1) }}h</span><small>淡入淡出 {{ schedule.transitionDuration }}s · 目标: {{ schedule.targets }}</small>
        </div>
      </section>

      <section class="debug-section">
        <h4>📊 性能统计</h4>
        <div class="info-item"><span>FPS:</span><strong :class="getFpsClass(performanceStats.fps)">{{ performanceStats.fps }}</strong></div>
        <div class="info-item"><span>帧时间:</span><strong>{{ performanceStats.frameTime.toFixed(2) }}ms</strong></div>
        <div class="info-item"><span>内存:</span><strong>{{ performanceStats.memoryUsage.toFixed(1) }}MB</strong></div>
      </section>

      <section class="debug-section">
        <h4>🎮 控制</h4>
        <div class="camera-sensitivity-info"><span>摄像机灵敏度</span><strong>{{ cameraSensitivity.toFixed(6) }} 弧度/像素</strong><small>{{ (cameraSensitivity * deviceDPI).toFixed(4) }} 弧度/英寸</small></div>
        <button class="debug-button" @click="emit('logDebugInfo')">📝 打印调试信息</button>
        <button class="debug-button" @click="goToDebugSceneViewer">🔍 高斯场景调试页面</button>
      </section>

      <slot name="extra-sections" />
    </div>
  </div>
  <button v-else class="debug-toggle-btn" type="button" aria-label="打开 Debug 面板" title="打开Debug面板" @click="togglePanel">
    <svg class="debug-toggle-icon" viewBox="0 0 24 24" fill="none" aria-hidden="true">
      <path d="M14.7 6.3a4.5 4.5 0 0 0-5.98 5.98L3.5 17.5a2.12 2.12 0 0 0 3 3l5.22-5.22a4.5 4.5 0 0 0 5.98-5.98l-2.95 2.95-2.7-.9-.9-2.7L14.7 6.3Z" />
    </svg>
  </button>
</template>

<script setup lang="ts">
/**
 * @changelog
 *   v1.9.0 - 阶段1：将环境面板开关移到内容栏，新增场景面板开关及其显隐事件。
 *            REQ: debugpanel-拆分-阶段1 TECH: scene-panel-phase1-framework
 *   v2.0.0 - 阶段2：移除已迁往 ScenePanel 的可视化、高斯、NPC、音频、物理及悬崖检测代码。
 *            REQ: debugpanel-拆分-阶段2 TECH: scene-panel-subpanel-migration
 *   v2.1.0 - 使用内联 SVG 渲染浮动开关图标，避免 emoji 在不同平台显示异常。
 *            REQ: debugpanel-icon-fix TECH: debug-panel-inline-icon
 * /@changelog
 *
 * @author DannyCheung
 */
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue';
import type { PerformanceStats } from '@tencent/viewer-sdk';
import { useLightCullingParams } from '../composables/useLightCullingParams';
import { useLightScheduleParams } from '../composables/useLightScheduleParams';
import { useEngineContextGetter } from '../composables/useEngineContext';
import { checkOpenidWhitelist } from '../utils/util';
import { resolveSceneUrlFromSiteUri } from '../utils/route-params';

interface Props {
  debugManager?: { getPerformanceStats?: () => PerformanceStats } | null;
  sceneManager?: unknown;
  cameraSensitivity?: number;
  environmentPanelVisible?: boolean;
  scenePanelVisible?: boolean;
}

const props = withDefaults(defineProps<Props>(), { debugManager: undefined, sceneManager: undefined, cameraSensitivity: 0.003, environmentPanelVisible: false, scenePanelVisible: false });
const emit = defineEmits<{ logDebugInfo: []; logRebaseInfo: []; toggleEnvironmentPanel: []; toggleScenePanel: [] }>();
const showDebugPanel = ref(false);
const enableSecondShare = ref(false);
const enableSecondShareVisible = ref(false);
const performanceStats = reactive<PerformanceStats>({ fps: 0, frameTime: 0, physicsTime: 0, renderTime: 0, memoryUsage: 0 });
const getCtx = useEngineContextGetter();
const { cullingParams, cullingRegistered, refreshSnapshot: refreshCullingSnapshot, setEnabled: setCullingEnabled, setMaxActiveLights } = useLightCullingParams(getCtx);
const { scheduleRegistered, scheduleCount, scheduledLightCount, activeOnCount, scheduleSummaries, refreshSnapshot: refreshScheduleSnapshot } = useLightScheduleParams(getCtx);
const cameraSensitivity = computed(() => props.cameraSensitivity || 0.003);
const deviceDPI = window.devicePixelRatio * 96;
let secondShareSeq = 0;
let updateTimer: ReturnType<typeof setInterval> | null = null;

function togglePanel(): void {
  showDebugPanel.value = !showDebugPanel.value;
}

function getFpsClass(fps: number): string {
  if (fps >= 50) return 'fps-good';
  if (fps >= 30) return 'fps-ok';
  return 'fps-bad';
}

function refresh(): void {
  const stats = props.debugManager?.getPerformanceStats?.();
  if (stats) Object.assign(performanceStats, stats);
  refreshCullingSnapshot();
  refreshScheduleSnapshot();
}

async function initSecondShareGate(): Promise<void> {
  try {
    enableSecondShareVisible.value = await checkOpenidWhitelist();
  } catch (error) {
    console.error('[DebugPanel] 二次分享 OpenID 校验失败:', error);
  }
}

function onEnableSecondShareChange(): void {
  secondShareSeq += 1;
  if (!window.wx?.miniProgram) return;
  window.wx.miniProgram.postMessage({
    data: { action: 'subRoot', isSubRoot: enableSecondShare.value, seq: secondShareSeq },
  });
}

async function goToDebugSceneViewer(): Promise<void> {
  const baseUrl = window.location.href.split('#')[0];
  const hash = window.location.hash || '';
  const queryIndex = hash.indexOf('?');
  const hashPath = (queryIndex >= 0 ? hash.slice(0, queryIndex) : hash).replace(/^#\//, '');
  const params = new URLSearchParams(queryIndex >= 0 ? hash.slice(queryIndex + 1) : '');
  params.set('showDebugViewer', 'true');
  const knownBasePaths = ['viewer2', 'debug-viewer', 'creative'];
  if (hashPath && !knownBasePaths.includes(hashPath.split(/[/?]/, 1)[0] || '')) {
    params.set('sceneUrl', await resolveSceneUrlFromSiteUri(hashPath));
  }
  window.open(`${baseUrl}#/debug-viewer?${params.toString()}`, '_blank');
}

function onKeydown(event: KeyboardEvent): void {
  if (event.key !== 'F1') return;
  event.preventDefault();
  togglePanel();
}

onMounted(() => {
  refresh();
  updateTimer = setInterval(refresh, 1000);
  document.addEventListener('keydown', onKeydown);
  void initSecondShareGate();
});

onUnmounted(() => {
  if (updateTimer) clearInterval(updateTimer);
  document.removeEventListener('keydown', onKeydown);
});
</script>

