<template>
  <div class="subpanel-content">
    <section>
      <h5>🌍 物理世界</h5>
      <div class="physics-info">
        <div class="info-item">
          <span>刚体数量:</span><strong>{{ physicsInfo.rigidBodyCount }}</strong>
        </div>
        <div class="info-item">
          <span>角色位置:</span><strong>{{ formatVector3(physicsInfo.characterPosition) }}</strong>
        </div>
        <div class="info-item">
          <span>角色朝向:</span><strong>{{ formatRotation(physicsInfo.characterRotation) }}</strong>
        </div>
        <div class="info-item">
          <span>在地面上:</span
          ><strong :class="physicsInfo.isCharacterGrounded ? 'grounded' : 'airborne'">{{
            physicsInfo.isCharacterGrounded ? '是' : '否'
          }}</strong>
        </div>
        <div class="info-item">
          <span>垂直速度:</span
          ><strong :class="getVelocityClass(physicsInfo.characterVerticalVelocity)"
            >{{ physicsInfo.characterVerticalVelocity.toFixed(2) }} m/s</strong
          >
        </div>
        <div class="info-item">
          <span>重力:</span><strong>{{ formatVector3(physicsInfo.worldGravity) }}</strong>
        </div>
        <button class="debug-button" type="button" @click="copyCharacterTransform">📋 复制角色 Transform</button>
        <button class="debug-button" type="button" @click="copyCharacterRawTransform">
          📋 复制角色（偏移前）Transform
        </button>
      </div>
    </section>

    <section class="cliff-section">
      <h5>🚫 悬崖检测</h5>
      <div class="cliff-detection-controls">
        <label class="debug-checkbox">
          <input v-model="cliffDetectionConfig.enabled" type="checkbox" @change="onCliffDetectionChange" />
          <span>启用悬崖检测</span>
        </label>
        <div v-if="cliffDetectionConfig.enabled" class="cliff-detection-options">
          <label class="control-label"
            >行为模式:
            <select v-model="cliffDetectionConfig.behaviorMode" @change="onCliffDetectionChange">
              <option value="block">阻止 (Block)</option>
              <option value="slide">滑动 (Slide)</option>
              <option value="slow">减速 (Slow)</option>
            </select>
          </label>
          <label class="control-label"
            >检测距离:
            <input
              v-model.number="cliffDetectionConfig.checkDistance"
              type="range"
              min="0.1"
              max="2"
              step="0.05"
              @input="onCliffDetectionConfigChange"
            />
            <span>{{ cliffDetectionConfig.checkDistance.toFixed(2) }}m</span>
          </label>
          <label class="control-label"
            >最大掉落高度:
            <input
              v-model.number="cliffDetectionConfig.maxFallDistance"
              type="range"
              min="0.5"
              max="10"
              step="0.5"
              @input="onCliffDetectionConfigChange"
            />
            <span>{{ cliffDetectionConfig.maxFallDistance.toFixed(1) }}m</span>
          </label>
          <label class="control-label"
            >安全边距:
            <input
              v-model.number="cliffDetectionConfig.safetyMargin"
              type="range"
              min="0.05"
              max="0.5"
              step="0.05"
              @input="onCliffDetectionConfigChange"
            />
            <span>{{ cliffDetectionConfig.safetyMargin.toFixed(2) }}m</span>
          </label>
        </div>
        <div class="status-card">
          <span>当前状态:</span
          ><strong :class="cliffDetectionConfig.enabled ? 'grounded' : 'disabled'">{{
            cliffDetectionConfig.enabled ? '启用' : '禁用'
          }}</strong>
          <span>行为模式:</span
          ><strong class="mode-indicator">{{ getModeDisplayName(cliffDetectionConfig.behaviorMode) }}</strong>
        </div>
      </div>
    </section>

    <button class="debug-button reset-button" type="button" @click="emit('resetPhysics')">🔄 重置物理世界</button>
  </div>
</template>

<script setup lang="ts">
/**
 * @changelog
 *   v1.0.0 - 从 DebugPanel 迁移物理信息、悬崖检测配置与物理世界重置操作。
 *            REQ: debugpanel-拆分-阶段2 TECH: scene-panel-physics-subpanel
 * /@changelog
 *
 * @author DannyCheung
 */
import { onMounted, onUnmounted, reactive } from 'vue';
import { CLIFF_DETECTION_CONFIG } from '@tencent/viewer-sdk';

interface Vector3Like {
  x: number;
  y: number;
  z: number;
}
interface PhysicsInfo {
  rigidBodyCount: number;
  characterPosition: Vector3Like | null;
  characterRotation: Vector3Like | null;
  isCharacterGrounded: boolean;
  characterVerticalVelocity: number;
  worldGravity: Vector3Like | null;
}

type CliffDetectionBehaviorMode = 'block' | 'slide' | 'slow';
type RuntimeDebugUpdate = {
  cliffDetectionEnabled?: boolean;
  cliffBehaviorMode?: CliffDetectionBehaviorMode;
  cliffDetectionConfig?: Partial<{
    checkDistance: number;
    maxFallDistance: number;
    safetyMargin: number;
  }>;
};

const props = defineProps<{
  debugManager?: { getPhysicsInfo?: () => Partial<PhysicsInfo> | null; getWorldOffset?: () => Vector3Like };
}>();
const emit = defineEmits<{ configChange: [config: RuntimeDebugUpdate]; resetPhysics: [] }>();

const physicsInfo = reactive<PhysicsInfo>({
  rigidBodyCount: 0,
  characterPosition: null,
  characterRotation: null,
  isCharacterGrounded: false,
  characterVerticalVelocity: 0,
  worldGravity: null,
});
const cliffDetectionConfig = reactive({
  enabled: CLIFF_DETECTION_CONFIG.ENABLED,
  behaviorMode: CLIFF_DETECTION_CONFIG.DEFAULT_BEHAVIOR_MODE as 'block' | 'slide' | 'slow',
  checkDistance: CLIFF_DETECTION_CONFIG.CHECK_DISTANCE,
  maxFallDistance: CLIFF_DETECTION_CONFIG.MAX_FALL_DISTANCE,
  safetyMargin: CLIFF_DETECTION_CONFIG.SAFETY_MARGIN,
});
let updateTimer: ReturnType<typeof setInterval> | null = null;

function refreshPhysicsInfo(): void {
  const latest = props.debugManager?.getPhysicsInfo?.();
  if (latest) Object.assign(physicsInfo, latest);
}

function onCliffDetectionChange(): void {
  emit('configChange', {
    cliffDetectionEnabled: cliffDetectionConfig.enabled,
    cliffBehaviorMode: cliffDetectionConfig.behaviorMode,
  });
}

function onCliffDetectionConfigChange(): void {
  emit('configChange', {
    cliffDetectionConfig: {
      checkDistance: cliffDetectionConfig.checkDistance,
      maxFallDistance: cliffDetectionConfig.maxFallDistance,
      safetyMargin: cliffDetectionConfig.safetyMargin,
    },
  });
}

function formatVector3(value: Vector3Like | null): string {
  return value ? `(${value.x.toFixed(2)}, ${value.y.toFixed(2)}, ${value.z.toFixed(2)})` : 'N/A';
}

function formatRotation(value: Vector3Like | null): string {
  return value ? `(${value.x}°, ${value.y}°, ${value.z}°)` : 'N/A';
}

function getVelocityClass(value: number): string {
  if (value > 1) return 'velocity-up';
  if (value < -1) return 'velocity-down';
  return 'grounded';
}

function getModeDisplayName(mode: string): string {
  return { block: '阻止', slide: '滑动', slow: '减速' }[mode] ?? mode;
}

async function copyCharacterTransform(): Promise<void> {
  if (!physicsInfo.characterPosition) return alert('无法获取角色位置');
  await writeTransform(physicsInfo.characterPosition);
}

async function copyCharacterRawTransform(): Promise<void> {
  if (!physicsInfo.characterPosition) return alert('无法获取角色位置');
  const offset = props.debugManager?.getWorldOffset?.() ?? { x: 0, y: 0, z: 0 };
  await writeTransform({
    x: physicsInfo.characterPosition.x + offset.x,
    y: physicsInfo.characterPosition.y + offset.y,
    z: physicsInfo.characterPosition.z + offset.z,
  });
}

async function writeTransform(position: Vector3Like): Promise<void> {
  const round = (value: number) => Math.round(value * 100) / 100;
  try {
    await navigator.clipboard.writeText(
      JSON.stringify(
        {
          position: { x: round(position.x), y: round(position.y), z: round(position.z) },
          rotation: physicsInfo.characterRotation ?? { x: 0, y: 0, z: 0 },
        },
        null,
        2,
      ),
    );
  } catch (error) {
    console.error('复制 Transform 失败:', error);
  }
}

onMounted(() => {
  refreshPhysicsInfo();
  updateTimer = setInterval(refreshPhysicsInfo, 1000);
});

onUnmounted(() => {
  if (updateTimer) clearInterval(updateTimer);
});
</script>

