import { ref } from 'vue';
import type { EngineContext, LightScheduleState, LightScheduleConfig } from '@tencent/viewer-sdk';
import { lightScheduleModule, getModule } from '@tencent/viewer-sdk';

/**
 * useLightScheduleParams — 定时开关灯 DebugPanel 状态封装。
 *
 * 设计遵循 useHdriParams 范式：
 * - `getCtx()` 工厂返回 `EngineContext | undefined`
 * - `refreshSnapshot` 按轮询读取快照
 */
export function useLightScheduleParams(getCtx: () => EngineContext | undefined) {
  /** 模块是否已注册 */
  const scheduleRegistered = ref(false);

  /** 调度配置条目数 */
  const scheduleCount = ref(0);

  /** 被调度的灯光总数 */
  const scheduledLightCount = ref(0);

  /** 当前处于「亮」状态的灯光数（factor > 0.01） */
  const activeOnCount = ref(0);

  /** 每条调度的配置概要 */
  const scheduleSummaries = ref<
    { name: string; onHour: number; offHour: number; transitionDuration: number; targets: string }[]
  >([]);

  /**
   * 从 lightScheduleModule 读取当前状态快照。
   * 模块未注册时静默跳过，`scheduleRegistered` 置 false。
   */
  function refreshSnapshot(): void {
    const ctx = getCtx();
    if (!ctx) return;

    try {
      const state = getModule<LightScheduleState>(ctx, lightScheduleModule);
      scheduleRegistered.value = state.enabled;
      scheduleCount.value = state.schedules.length;
      scheduledLightCount.value = state.lights.size;

      let onCount = 0;
      for (const sl of state.lights.values()) {
        if (sl.target > 0.01) onCount++;
      }
      activeOnCount.value = onCount;

      scheduleSummaries.value = state.schedules.map((s: LightScheduleConfig) => ({
        name: s.name ?? '(无名)',
        onHour: s.onHour,
        offHour: s.offHour,
        transitionDuration: s.transitionDuration ?? 1.0,
        targets: s.targets.join(', '),
      }));
    } catch {
      scheduleRegistered.value = false;
      scheduleCount.value = 0;
      scheduledLightCount.value = 0;
      activeOnCount.value = 0;
      scheduleSummaries.value = [];
    }
  }

  return {
    scheduleRegistered,
    scheduleCount,
    scheduledLightCount,
    activeOnCount,
    scheduleSummaries,
    refreshSnapshot,
  };
}
