/**
 * @changelog
 *   v1.0.0 - 初始实现：封装 lightProbeModule.xxx(ctx, ...) 实例 API 的快照读取 + 命令式 action
 *            （烘焙 / 导出 / 运行时开关 / 强度 / 插值 / cubeSize / 体积盒增删改 / 探针可视化）。
 *            DebugPanel 仅 import 本 composable，不直接依赖 viewer-sdk 的 LightProbeModule 类。
 *            REQ: 20260724-light-probe-volume
 * /@changelog
 *
 * @author v_weiqinlin
 */
import { reactive, ref } from 'vue';
import type { EngineContext, LightProbeInfo, LightProbeVolumeBox } from '@tencent/viewer-sdk';
import { lightProbeModule } from '@tencent/viewer-sdk';

/** 新增体积盒默认值（以角色附近的 10×4×10 盒为起点，贴地 2 层） */
function defaultBox(): LightProbeVolumeBox {
  return {
    center: [0, 1, 0],
    size: [10, 4, 10],
    xzSpacing: 5,
    yLayers: 2,
    ySpacing: 2,
  };
}

/**
 * useLightProbeParams — Light Probe 面板状态 + 命令式 action 封装
 *
 * 设计要点（对齐 useHdriParams）：
 * - `getCtx()` 返回 `EngineContext | undefined`（sceneManager 可能尚未初始化）。
 * - 所有 action try/catch 探测 `lightProbeModule` 是否注册（lighting.lightProbeVolume 缺失即未注册）。
 * - `refresh` 读取 module 当前摘要写入 reactive info + boxes；`registered` 控制 DebugPanel 分组显隐。
 */
export function useLightProbeParams(getCtx: () => EngineContext | undefined) {
  /** 模块是否注册（分组显隐） */
  const registered = ref(false);
  /** 只读摘要（module.getInfo 快照） */
  const info = reactive<LightProbeInfo>({
    enabled: true,
    hasData: false,
    boxCount: 0,
    volumeCount: 0,
    probeTotal: 0,
    intensity: 1.0,
    interpolation: 'trilinear',
    cubeSize: 64,
    baking: false,
    visualizerOn: false,
  });
  /** 可编辑的体积盒数组（本地副本，编辑后 syncBoxes 回写 module） */
  const boxes = ref<LightProbeVolumeBox[]>([]);
  /** 是否正在烘焙 */
  const isBaking = ref(false);
  /** 烘焙进度（0~1） */
  const bakeProgress = ref(0);

  /**
   * 从 lightProbeModule 当前状态同步 info + boxes。
   * 未注册时置 registered=false 并静默返回 false。
   */
  function refresh(): boolean {
    const ctx = getCtx();
    if (!ctx) return false;
    try {
      const snapshot = lightProbeModule.getInfo(ctx);
      Object.assign(info, snapshot);
      boxes.value = lightProbeModule.getBoxes(ctx).map((b) => ({ ...b }));
      registered.value = true;
      return true;
    } catch {
      registered.value = false;
      return false;
    }
  }

  /** 离线烘焙当前体积盒并应用运行时 */
  async function bake(): Promise<void> {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      isBaking.value = true;
      bakeProgress.value = 0;
      await lightProbeModule.bake(ctx, (done, total) => {
        bakeProgress.value = total > 0 ? done / total : 0;
      });
    } catch (err) {
      console.warn('⚠️ Light Probe 烘焙失败（模块未注册或无体积盒/高斯未加载）:', err);
    } finally {
      isBaking.value = false;
      refresh();
    }
  }

  /** 导出烘焙数据为 .lpv 文件 */
  function exportData(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      lightProbeModule.exportData(ctx);
    } catch (err) {
      console.warn('⚠️ Light Probe 导出失败（尚无烘焙数据）:', err);
    }
  }

  /** 运行时注入开关 */
  function setEnabled(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      lightProbeModule.setRuntimeEnabled(ctx, info.enabled);
    } catch {
      /* 未注册，忽略 */
    }
  }

  /** 漫反射强度 */
  function applyIntensity(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      lightProbeModule.setIntensity(ctx, info.intensity);
    } catch {
      /* 未注册，忽略 */
    }
  }

  /** 插值方式 */
  function applyInterpolation(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      lightProbeModule.setInterpolation(ctx, info.interpolation);
    } catch {
      /* 未注册，忽略 */
    }
  }

  /** 烘焙 cubemap 分辨率 */
  function applyCubeSize(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      lightProbeModule.setCubeSize(ctx, info.cubeSize);
    } catch {
      /* 未注册，忽略 */
    }
  }

  /** 探针可视化开关 */
  function setVisualizer(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      lightProbeModule.setVisualizerEnabled(ctx, info.visualizerOn);
    } catch {
      /* 未注册，忽略 */
    }
  }

  /** 把本地 boxes 回写 module */
  function syncBoxes(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      lightProbeModule.setBoxes(ctx, boxes.value);
      refresh();
    } catch {
      /* 未注册，忽略 */
    }
  }

  /** 新增一个体积盒 */
  function addBox(): void {
    boxes.value.push(defaultBox());
    syncBoxes();
  }

  /** 移除指定体积盒 */
  function removeBox(index: number): void {
    boxes.value.splice(index, 1);
    syncBoxes();
  }

  return {
    // state
    registered,
    info,
    boxes,
    isBaking,
    bakeProgress,
    // actions
    refresh,
    bake,
    exportData,
    setEnabled,
    applyIntensity,
    applyInterpolation,
    applyCubeSize,
    setVisualizer,
    syncBoxes,
    addBox,
    removeBox,
  };
}
